function getSelectValue(clientId) {
    if (!clientId) {
        return "";
    }
    var el = document.getElementById(clientId);
    return el ? el.value : "";
}

function readFilterConfig() {
    filterConfig = window.ssdDashFilterConfig || filterConfig || {};
    return filterConfig;
}

function isFilterValueActive(val) {
    return val !== null && val !== undefined && val !== "" && val !== "0" && val !== "-1";
}

function getFiltersFromDom() {
    readFilterConfig();
    return {
        yearId: getSelectValue(filterConfig.yearId),
        semester: getSelectValue(filterConfig.semesterId),
        scienceId: getSelectValue(filterConfig.scienceId),
        courseId: getSelectValue(filterConfig.courseId),
        classId: getSelectValue(filterConfig.classId)
    };
}

function validateFilters(filters) {
    if (!isFilterValueActive(filters.yearId)) {
        return "Vui lòng chọn Năm học.";
    }
    if (!isFilterValueActive(filters.semester)) {
        return "Vui lòng chọn Học kỳ.";
    }
    return "";
}

function fillFilterDropdown(clientId, rows, valueField, textField) {
    var el = document.getElementById(clientId);
    var i;
    var row;
    if (!el) {
        return;
    }
    while (el.options.length > 0) {
        el.remove(0);
    }
    var defaultOpt = document.createElement("option");
    defaultOpt.value = "";
    defaultOpt.text = "--Chọn--";
    el.appendChild(defaultOpt);
    if (!rows || rows.length === 0) {
        return;
    }
    for (i = 0; i < rows.length; i++) {
        row = rows[i];
        var opt = document.createElement("option");
        opt.value = row[valueField] !== null && row[valueField] !== undefined ? String(row[valueField]) : "";
        opt.text = row[textField] !== null && row[textField] !== undefined ? String(row[textField]) : "";
        el.appendChild(opt);
    }
}

function fillFilterDropdownPreserve(clientId, rows, valueField, textField, preserveValue) {
    var el = document.getElementById(clientId);
    var currentValue = preserveValue !== undefined && preserveValue !== null ? String(preserveValue) : (el ? el.value : "");
    fillFilterDropdown(clientId, rows, valueField, textField);
    if (!el || !isFilterValueActive(currentValue)) {
        return;
    }
    el.value = currentValue;
    if (el.value !== currentValue) {
        el.value = "";
    }
}

function loadFilterList(listType, scienceId, courseId, callback) {
    postJson({
        action: "filters",
        listType: listType,
        scienceId: scienceId || "",
        courseId: courseId || ""
    }, function (success, message, data) {
        if (!success) {
            callback(false, message, []);
            return;
        }
        callback(true, "", data && data.items ? data.items : []);
    });
}

function refreshClassDropdown(callback) {
    readFilterConfig();
    var scienceId = getSelectValue(filterConfig.scienceId);
    var courseId = getSelectValue(filterConfig.courseId);
    var currentClassId = getSelectValue(filterConfig.classId);
    loadFilterList(3, scienceId, courseId, function (success, message, rows) {
        if (success) {
            fillFilterDropdownPreserve(filterConfig.classId, rows, "ClassID", "ClassName", currentClassId);
        }
        if (typeof callback === "function") {
            callback();
        }
    });
}

function onScienceOrCourseFilterChange() {
    refreshClassDropdown(fetchDashboard);
}

function onYearSemesterClassFilterChange() {
    fetchDashboard();
}

function bindFilterAutoReload() {
    readFilterConfig();
    var yearEl = document.getElementById(filterConfig.yearId);
    var semesterEl = document.getElementById(filterConfig.semesterId);
    var scienceEl = document.getElementById(filterConfig.scienceId);
    var courseEl = document.getElementById(filterConfig.courseId);
    var classEl = document.getElementById(filterConfig.classId);

    if (yearEl) {
        yearEl.addEventListener("change", onYearSemesterClassFilterChange);
    }
    if (semesterEl) {
        semesterEl.addEventListener("change", onYearSemesterClassFilterChange);
    }
