        classEl.addEventListener("change", onYearSemesterClassFilterChange);
    }
    if (scienceEl) {
        scienceEl.addEventListener("change", onScienceOrCourseFilterChange);
    }
    if (courseEl) {
        courseEl.addEventListener("change", onScienceOrCourseFilterChange);
    }
