function getSelectValue(clientId) {
    if (!clientId) {
        return "";
    }
    var el = document.getElementById(clientId);
    if (!el) {
        return "";
    }
    if (el.classList && el.classList.contains("scs-ms-wrap")) {
        var allCheck = el.querySelector(".scs-ms-check-all");
        if (allCheck && allCheck.checked) {
            return "";
        }
        var checks = el.querySelectorAll(".scs-ms-check:checked");
        var values = [];
        var i;
        for (i = 0; i < checks.length; i++) {
            values.push(checks[i].value);
        }
        return values.join(",");
    }
    return el.value;
}

function readFilterConfig() {
    filterConfig = window.ssdDashFilterConfig || filterConfig || {};
    return filterConfig;
}

function isFilterValueActive(val) {
    if (val === null || val === undefined || val === "") {
        return false;
    }
    if (val === "0" || val === "-1") {
        return false;
    }
    if (String(val).replace(/,/g, "").trim() === "") {
        return false;
    }
    return true;
}

function getFiltersFromDom() {
    readFilterConfig();
    return {
        yearId: getSelectValue(filterConfig.yearId),
        semester: getSelectValue(filterConfig.semesterId),
        scienceId: getSelectValue(filterConfig.scienceId),
        courseId: getSelectValue(filterConfig.courseId),
        classId: getSelectValue(filterConfig.classId),
        fromDate: filterConfig.fromDate ? getSelectValue(filterConfig.fromDate) : "",
        toDate: filterConfig.toDate ? getSelectValue(filterConfig.toDate) : ""
    };
}

function validateFilters(filters) {
    if (!isFilterValueActive(filters.yearId)) {
        return "Vui lòng chọn Năm học.";
    }
    if (!isFilterValueActive(filters.semester)) {
        return "Vui lòng chọn Học kỳ.";
    }
    if (!filters.fromDate) {
        return "Vui lòng chọn Từ ngày.";
    }
    if (!filters.toDate) {
        return "Vui lòng chọn Đến ngày.";
    }
    if (filters.fromDate > filters.toDate) {
        return "Từ ngày không được lớn hơn Đến ngày.";
    }
    return "";
}

function updateMultiSelectCount(container) {
    var wrap = container;
    if (!wrap || !wrap.classList) {
        return;
    }
    if (!wrap.classList.contains("scs-ms-wrap")) {
        wrap = wrap.closest ? wrap.closest(".scs-ms-wrap") : null;
        if (!wrap) {
            return;
        }
    }
    var allCheck = wrap.querySelector(".scs-ms-check-all");
    var checks = wrap.querySelectorAll(".scs-ms-check");
    var count = 0;
    var i;
    for (i = 0; i < checks.length; i++) {
        if (checks[i].checked) {
            count++;
        }
    }
    var label = wrap.querySelector(".scs-ms-label");
    var badge = wrap.querySelector(".scs-ms-count");
    if (allCheck && allCheck.checked) {
        if (label) {
            label.textContent = "Tất cả";
        }
        if (badge) {
            badge.className = "badge bg-secondary scs-ms-count d-none";
        }
    } else {
        if (label) {
            label.textContent = "Đã chọn " + count;
        }
        if (badge) {
            badge.textContent = count;
            badge.className = "badge bg-secondary scs-ms-count";
        }
    }
}

function updateMultiSelectAllState(container) {
    var checks = container.querySelectorAll(".scs-ms-check");
    var allCheck = container.querySelector(".scs-ms-check-all");
    if (!allCheck) {
        return;
    }
    var allChecked = true;
    var i;
    for (i = 0; i < checks.length; i++) {
        if (!checks[i].checked) {
            allChecked = false;
            break;
        }
    }
    allCheck.checked = allChecked;
}

function bindMultiSelectEvents(container) {
    if (!container) {
        return;
    }
    var menu = container.querySelector(".scs-ms-menu");
    if (menu && !menu.getAttribute("data-ms-bound")) {
        menu.setAttribute("data-ms-bound", "1");
    }
    updateMultiSelectCount(container);
}

function closeAllMultiSelects() {
    var openWraps = document.querySelectorAll(".scs-ms-wrap.open");
    var i;
    for (i = 0; i < openWraps.length; i++) {
        openWraps[i].classList.remove("open");
    }
}

var debounceTimers = {};

function debouncedFilterChange(container) {
    if (!container) {
        return;
    }
    var id = container.id || "generic";
    if (debounceTimers[id]) {
        clearTimeout(debounceTimers[id]);
    }
    debounceTimers[id] = setTimeout(function () {
        debounceTimers[id] = null;
        if (id.indexOf("Class") >= 0) {
            onClassFilterChange();
        } else {
            onScienceOrCourseFilterChange();
        }
    }, 500);
}

function initMultiSelectDropdowns() {
    document.addEventListener("change", function (e) {
        var target = e.target;
        if (!target || !target.closest) {
            return;
        }
        var menu = target.closest(".scs-ms-menu");
        if (!menu) {
            return;
        }
        var container = menu.closest(".scs-ms-wrap");
        if (!container) {
            return;
        }

        if (target.classList.contains("scs-ms-check-all")) {
            var allChecked = target.checked;
            var checks = menu.querySelectorAll(".scs-ms-check");
            var i;
            for (i = 0; i < checks.length; i++) {
                checks[i].checked = allChecked;
            }
            updateMultiSelectCount(container);
            debouncedFilterChange(container);
        } else if (target.classList.contains("scs-ms-check")) {
            updateMultiSelectAllState(container);
            updateMultiSelectCount(container);
            debouncedFilterChange(container);
        }
    });

    document.addEventListener("click", function (e) {
        var trigger = e.target.closest(".scs-ms-trigger");
        if (trigger) {
            var wrap = trigger.closest(".scs-ms-wrap");
            if (wrap) {
                e.preventDefault();
                var isOpen = wrap.classList.contains("open");
                closeAllMultiSelects();
                if (!isOpen) {
                    wrap.classList.add("open");
                }
            }
            return;
        }
        if (e.target.closest(".scs-ms-menu")) {
            return;
        }
        closeAllMultiSelects();
    });
}

function fillFilterDropdown(clientId, rows, valueField, textField) {
    var container = document.getElementById(clientId);
    if (!container) {
        return;
    }
    var menu = container.querySelector(".scs-ms-menu");
    if (!menu) {
        return;
    }
    menu.innerHTML = "";
    var allLabel = document.createElement("label");
    allLabel.className = "scs-ms-item scs-ms-all-item";
    var allCheck = document.createElement("input");
    allCheck.type = "checkbox";
    allCheck.className = "scs-ms-check-all";
    allCheck.checked = true;
    allLabel.appendChild(allCheck);
    allLabel.appendChild(document.createTextNode(" Tất cả"));
    menu.appendChild(allLabel);
    var allDiv = document.createElement("div");
    allDiv.className = "scs-ms-divider";
    menu.appendChild(allDiv);
    var emptyEl = document.createElement("div");
    emptyEl.className = "scs-ms-empty d-none";
    emptyEl.textContent = "Không có dữ liệu";
    menu.appendChild(emptyEl);
    if (rows && rows.length > 0) {
        var i;
        var row;
        for (i = 0; i < rows.length; i++) {
            row = rows[i];
            var value = row[valueField] !== null && row[valueField] !== undefined ? String(row[valueField]) : "";
            var text = row[textField] !== null && row[textField] !== undefined ? String(row[textField]) : "";
            var label = document.createElement("label");
            label.className = "scs-ms-item";
            var check = document.createElement("input");
            check.type = "checkbox";
            check.className = "scs-ms-check";
            check.value = value;
            check.checked = true;
            label.appendChild(check);
            label.appendChild(document.createTextNode(" " + text));
            menu.appendChild(label);
        }
    } else {
        allLabel.className = "scs-ms-item scs-ms-all-item d-none";
        allDiv.className = "scs-ms-divider d-none";
        emptyEl.className = "scs-ms-empty";
    }
    bindMultiSelectEvents(container);
    updateMultiSelectCount(container);
}

function fillFilterDropdownPreserve(clientId, rows, valueField, textField, preserveValue) {
    fillFilterDropdown(clientId, rows, valueField, textField);
    var container = document.getElementById(clientId);
    if (!container) {
        return;
    }
    if (!preserveValue || String(preserveValue).trim() === "") {
        var allCb = container.querySelector(".scs-ms-check-all");
        if (allCb) {
            allCb.checked = true;
        }
        updateMultiSelectCount(container);
        return;
    }
    var savedValues = String(preserveValue).split(",");
    var checks = container.querySelectorAll(".scs-ms-check");
    var i;
    var k;
    for (i = 0; i < checks.length; i++) {
        checks[i].checked = false;
    }
    var allCb2 = container.querySelector(".scs-ms-check-all");
    if (allCb2) {
        allCb2.checked = false;
    }
    for (i = 0; i < checks.length; i++) {
        for (k = 0; k < savedValues.length; k++) {
            if (checks[i].value === savedValues[k]) {
                checks[i].checked = true;
                break;
            }
        }
    }
    updateMultiSelectCount(container);
}

function loadFilterList(listType, scienceId, courseId, callback) {
    postJson({
        action: "filters",
        listType: listType,
        scienceId: scienceId || "",
        courseId: courseId || ""
    }, function (success, message, data) {
        if (!success) {
            callback(false, message, []);
            return;
        }
        callback(true, "", data && data.items ? data.items : []);
    });
}

function refreshClassDropdown(callback) {
    readFilterConfig();
    var scienceId = getSelectValue(filterConfig.scienceId);
    var courseId = getSelectValue(filterConfig.courseId);
    var currentClassId = getSelectValue(filterConfig.classId);
    loadFilterList(3, scienceId, courseId, function (success, message, rows) {
        if (success) {
            fillFilterDropdownPreserve(filterConfig.classId, rows, "ClassID", "ClassName", currentClassId);
        }
        if (typeof callback === "function") {
            callback();
        }
    });
}

function onScienceOrCourseFilterChange() {
    refreshClassDropdown(fetchDashboard);
}

function onClassFilterChange() {
    fetchDashboard();
}

function onYearSemesterClassFilterChange() {
    fetchDashboard();
}

function bindFilterAutoReload() {
    readFilterConfig();
    var yearEl = document.getElementById(filterConfig.yearId);
    var semesterEl = document.getElementById(filterConfig.semesterId);
    var fromDateEl = filterConfig.fromDate ? document.getElementById(filterConfig.fromDate) : null;
    var toDateEl = filterConfig.toDate ? document.getElementById(filterConfig.toDate) : null;

    if (yearEl) {
        yearEl.addEventListener("change", onYearSemesterClassFilterChange);
    }
    if (semesterEl) {
        semesterEl.addEventListener("change", onYearSemesterClassFilterChange);
    }
    if (fromDateEl) {
        fromDateEl.addEventListener("change", onYearSemesterClassFilterChange);
    }
    if (toDateEl) {
        toDateEl.addEventListener("change", onYearSemesterClassFilterChange);
    }
    initMultiSelectDropdowns();
}

function loadDashboardData(callback) {
    var filters = getFiltersFromDom();
    postJson({
        action: "data",
        viewType: currentView,
        yearId: filters.yearId,
        semester: filters.semester,
        scienceId: filters.scienceId,
        courseId: filters.courseId,
        classId: filters.classId,
        fromDate: filters.fromDate,
        toDate: filters.toDate
    }, callback);
}
